const STAGE = 'web';
const MAX_MINUTES = 90;
const BODY = "D="$R/discovery"

python3 - "$D/hosts.txt" "$D/host_ip.json" "$R/ports/open.txt" "$R/scope/urls.txt" > targets.txt <<'PY'
import json, sys
from pathlib import Path
hosts_f, map_f, open_f, urls_f = sys.argv[1:5]
read = lambda p: [l.strip() for l in Path(p).read_text().splitlines() if l.strip()] if Path(p).exists() else []
hosts = read(hosts_f)
host_ip = json.loads(Path(map_f).read_text()) if Path(map_f).exists() else {}
by_ip = {}
for h, ips in host_ip.items():
    for i in ips:
        by_ip.setdefault(i, []).append(h)
t = set(hosts)
for line in read(open_f):
    ip, _, port = line.rpartition(":")
    t.add(f"{ip}:{port}")
    if port not in ("80", "443"):
        for h in sorted(by_ip.get(ip, []))[:25]:
            t.add(f"{h}:{port}")
t.update(read(urls_f))
print("\n".join(sorted(t)))
