import hashlib, json
seen, out = set(), []
for line in open("httpx.jsonl"):
    try:
        r = json.loads(line)
    except ValueError:
        continue
    if r.get("failed"):
        continue
    url = r.get("url", "")
    if not url or url in seen:
        continue
    seen.add(url)
    tls = r.get("tls") or {}
    tech = sorted(r.get("tech") or [])
    rec = {"url": url, "host": (r.get("host") or "").lower(), "ip": r.get("host_ip") or (r.get("a") or [""])[0],
           "port": int(r.get("port") or 0), "scheme": r.get("scheme", ""), "status_code": r.get("status_code", 0),
           "title": (r.get("title") or "")[:200], "tech": tech, "server": r.get("webserver", ""),
           "favicon": str(r.get("favicon", "") or ""), "tls_cn": tls.get("subject_cn", ""),
           "cdn": r.get("cdn_name", "") if r.get("cdn") else ""}
    basis = [rec["status_code"], rec["title"], tech, rec["server"], rec["favicon"], rec["tls_cn"]]
    rec["fingerprint"] = hashlib.sha1(json.dumps(basis).encode()).hexdigest()[:16]
    out.append(rec)
with open("web.jsonl", "w") as fh:
    for o in out:
        fh.write(json.dumps(o) + "\n")
with open("result.json", "w") as fh:
    json.dump({"web_targets": sum(1 for _ in open("targets.txt")), "web_live": len(out)}, fh)
